const R=0.1,HW=2,MAXS=40,TOL=1e-5,Z0=1.7,AS=0.3;
const half=k=>HW/Math.sqrt(k);
const loss=(x,z,k)=>0.5*(z*z+k*x*x);
const out=s=>Math.abs(s.x)>half(s.k)||Math.abs(s.z)>HW;
const word=s=>out(s)?'diverged':loss(s.x,s.z,s.k)<TOL?'converged':s.n>=MAXS?'stopped at 40 steps':s.on?'running':'paused';
const over=s=>{const w=word(s);return w!=='running'&&w!=='paused';};
function adv(s,i){if(over(s))return s;const a=i.learningRate,x=s.x-a*s.k*s.x,z=s.z-a*s.z;return{...s,x,z,n:s.n+1,path:s.path.concat([[x,z]])};}
const lift=(p,k)=>{const h=half(k),x=Math.max(-h,Math.min(h,p[0])),z=Math.max(-HW,Math.min(HW,p[1]));return[x,0.5*loss(x,z,k)+0.04,z];};
const fresh=(on,ghost,k)=>{const x0=0.1*half(k);return{x:x0,z:Z0,n:0,on,path:[[x0,Z0]],ghost,k};};
const keep=s=>s.n>0?s.path.map(p=>lift(p,s.k)):s.ghost;
export function initialState({inputs}){return fresh(false,[],inputs.steepCurvature);}
export function reduce({state:s,event:e,inputs}){
 if(e.type==='step')return !s.on||over(s)||e.tick%6?s:adv(s,inputs);
 if(e.type==='parameter')return fresh(s.on,keep(s),e.parameter==='steepCurvature'?e.value:s.k);
 if(e.type!=='action')return s;
 if(e.action==='run')return over(s)?s:{...s,on:true};
 if(e.action==='pause')return{...s,on:false};
 if(e.action==='stepOnce')return adv({...s,on:false},inputs);
 if(e.action==='newRun')return fresh(false,keep(s),s.k);
 return s;
}
export function evaluate({inputs,state}){
 const s=state||initialState({inputs}),k=s.k,L=loss(s.x,s.z,k),gx=k*s.x,gz=s.z,g=Math.hypot(gx,gz),h=Math.SQRT1_2,p=lift([s.x,s.z],k);
 const show=!out(s)&&g*AS>0.05;
 return{nodes:{
  bowl:{scale:[1/Math.sqrt(k),1,1]},
  ball:{position:[p[0],p[1]-0.04+R,p[2]]},
  slope:show?{visible:true,quaternion:[gz/g*h,0,-gx/g*h,h],scale:[1,g*AS,1]}:{visible:false},
  trail:{points:s.path.map(q=>lift(q,k))},
  ghost:{points:s.ghost}},
  readouts:{status:word(s),mult:1-inputs.learningRate*k,limit:2/k,loss:L,steps:s.n}};
}

